/**
 * Pure data for the context-select tool, generated by the shared factory in
 * context-mark.ts (context-select and context-unselect differ only in name
 * and copy). No logic lives here — see src/tools/context-mark.ts.
 */

import type { Static } from "typebox";

import { makeMarkToolDefinition } from "./context-mark.ts";

export const CONTEXT_SELECT_TOOL_DEFINITION = makeMarkToolDefinition("select");
export const CONTEXT_SELECT_PARAMETERS = CONTEXT_SELECT_TOOL_DEFINITION.parameters;

export type ContextSelectParams = Static<typeof CONTEXT_SELECT_PARAMETERS>;
